+        // Outside: outer family ascending, then holes from the core back.
+        let o: Vec<u64> = [(0, true), (1, true), (3, false), (0, false)]
+            .iter()
+            .map(|&(k, f)| PassStart::Outside.rank(k, 3, f))
+            .collect();
+        assert!(o.windows(2).all(|w| w[0] < w[1]), "{o:?}");
